   181          /* {0,1,2,4,8} x { 0x00000000 .. 0xffffffff }
   182           *   -> { 0x000000000 .. 0x7fffffff8 } */
   183          s = exif_format_get_size(entry->format) * entry->components;
   184          if ((s < entry->components) || (s == 0)){
   185                  return 0;
   186          }
