   189           * Size? If bigger than 4 bytes, the actual data is not
   190           * in the entry but somewhere else (offset).
   191           */
   192          if (s > 4)
   193                  doff = exif_get_long (d + offset + 8, data->priv->order);
   194          else
   195                  doff = offset + 8;
